import{_ as t,o as r,c as l,a2 as o}from"./chunks/framework.BV21bweQ.js";const c=JSON.parse('{"title":"当前时代","description":"","frontmatter":{},"headers":[],"relativePath":"表层/历史/当前时代.md","filePath":"表层/历史/当前时代.md","lastUpdated":1787066340000}'),e={name:"表层/历史/当前时代.md"};function i(n,a,s,h,p,u){return r(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="当前时代" tabindex="-1">当前时代 <a class="header-anchor" href="#当前时代" aria-label="Permalink to &quot;当前时代&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>当前时代指黑暗时代结束后、以<strong>鹿国与熊国</strong>两极对峙为特征的冷战时期。大陆格局由两大强国主导，新兴的狼国在夹缝中谋求生存。故事的起点，位于狼国境内的红星孤儿院。</p><h2 id="鹿熊冷战的根源" tabindex="-1">鹿熊冷战的根源 <a class="header-anchor" href="#鹿熊冷战的根源" aria-label="Permalink to &quot;鹿熊冷战的根源&quot;">​</a></h2><p>冷战的根本矛盾，是双方对同一片故土的双重宣称：</p><ul><li><strong>熊族的宣称</strong>：熊族在共同体末期的内斗中被排挤，被迫举族北迁求生。数百年间，他们生活质量低下，始终怀念共同体时期的红色旗帜与五星，收复共同体核心故土成为族群执念。熊族主张，那片土地属于共同体，而共同体属于包括熊族在内的所有公民。</li><li><strong>鹿族的宣称</strong>：鹿族占据该区域后，经数百年经营与发展，已将其视为本族的实际故土，是族群繁衍与科技发展的根基，因此坚决捍卫领土主权。</li></ul><p>熊族的宣称基于共同体的历史法理，鹿族的宣称基于数百年的现实存续，两者皆无对错可言，却因执念与生存而无法调和，成为冷战无法化解的根源。</p><h2 id="两极格局" tabindex="-1">两极格局 <a class="header-anchor" href="#两极格局" aria-label="Permalink to &quot;两极格局&quot;">​</a></h2><h3 id="鹿国" tabindex="-1">鹿国 <a class="header-anchor" href="#鹿国" aria-label="Permalink to &quot;鹿国&quot;">​</a></h3><ul><li><strong>核心优势</strong>：全大陆最先进的科技水平、精锐的常规军队、独一无二的<strong>法师军团</strong>（高精尖战略威慑）</li><li><strong>国家体制</strong>：相对分散，学术氛围浓厚，各研究机构、地方势力拥有较大自主权，类似联邦或邦联制——这既是创新活力的来源，也是决策效率低下的根源</li><li><strong>战略劣势</strong>：常规军力（尤其是陆军规模）远逊于熊国，高度依赖法师力量进行战略平衡</li></ul><h3 id="熊国" tabindex="-1">熊国 <a class="header-anchor" href="#熊国" aria-label="Permalink to &quot;熊国&quot;">​</a></h3><ul><li><strong>核心优势</strong>：体量庞大到令人窒息的常规军队（&quot;钢铁洪流&quot;）、强大的工业基础、极高的民众凝聚力与战斗意志</li><li><strong>国家体制</strong>：高度集中化、集权化，决策高效、动员能力强；但已出现军国主义的修正倾向，与共同体的原始红色理想渐行渐远</li><li><strong>战略劣势</strong>：几乎没有成体系的法师力量；极北之地的恶劣环境限制了农业发展，粮食供应长期紧张；科技水平相对鹿国落后</li></ul><h2 id="核威慑与代理人战争" tabindex="-1">核威慑与代理人战争 <a class="header-anchor" href="#核威慑与代理人战争" aria-label="Permalink to &quot;核威慑与代理人战争&quot;">​</a></h2><p>鹿国率先研发并拥有少量核武器，熊国随后跟进。由于远程投放手段不完善、核弹头数量有限，核威慑的真实效用被限制，更多是政治筹码。</p><p>由于直接开战的代价过高，鹿熊双方将竞争焦点转移到对<strong>中间地带国家</strong>的争夺上，通过扶持代理人、争夺话语权来扩大自身阵营。</p><h3 id="环形山计划" tabindex="-1">环形山计划 <a class="header-anchor" href="#环形山计划" aria-label="Permalink to &quot;环形山计划&quot;">​</a></h3><p>鹿族以&quot;地质地貌研究&quot;为名启动了核弹研发，代号&quot;环形山计划&quot;——取自大陆上随处可见的或大或小的环形山。</p><p>核弹试爆成功后，鹿族惊恐地发现，爆心原地直接形成了一座<strong>与大陆上古环形山一模一样的全新环形山</strong>。大陆上的古环形山究竟从何而来，始终没有确切解释，而鹿族亲手复刻了这种痕迹。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></blockquote><p>此后，鹿族将核弹作为冷战中的&quot;战略威慑筹码&quot;，始终不敢真正使用；对毁灭力量的恐惧进一步加深了鹿族的厌战思潮。</p><h2 id="狮族战争" tabindex="-1">狮族战争 <a class="header-anchor" href="#狮族战争" aria-label="Permalink to &quot;狮族战争&quot;">​</a></h2><p>狮族世代占据<strong>六边形沙漠</strong>。这片沙漠温度奇高，与周边环境差异鲜明，且近百年持续升温，最终成为无活物可生存的无人区，狮族面临种族存续的燃眉之急。沙漠岩石层中蕴藏橙黄色的高能结晶，狮族将其磨成粉末作为极高能炸药、整块作为极高能燃料；此外，狮族还掌握着来历不明的&quot;异域科技&quot;，由此获得了抗衡鹿熊的实力。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></blockquote><p>战争是黑暗时代结束后大陆第一次真正意义上的大规模热武器战争。双方热武器体系均不成熟，战争惨烈程度堪比&quot;绞肉机&quot;：</p><ul><li>狮族自身数量稀少，侵略部队以仆从族（豺族等）为主，在前线与鹿族展开绞肉战</li><li>鹿族热武器体系不成熟，主力部队仍为法师，面对人海战术与结晶火炮轰炸，伤亡惨重，成为黑暗时代后损失最惨重的一次战争，直接催生了普遍的<strong>厌战思潮</strong></li><li>熊族在北线磨合并练硬了装甲部队，损失有限，战后形成对鹿族的压倒性陆军优势</li><li>狼族通过有限参与看清了工业化热武器战争的威力，转而积极发展热武器与核武器</li></ul><p>战争末期，狮族首都陷落，行政机构瘫痪。狮族单方面投降却未被认可，鹿熊联军仍继续进攻。最终狮族十不存一，幸存者几乎都是老弱病残，政府流亡，沦为<strong>仅在地图上存在的国家</strong>。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/人物/拉斯塔" class="layer-link" data-layer="中层">拉斯塔</a></p></blockquote><h2 id="狼国-危险的平衡者" tabindex="-1">狼国：危险的平衡者 <a class="header-anchor" href="#狼国-危险的平衡者" aria-label="Permalink to &quot;狼国：危险的平衡者&quot;">​</a></h2><p>狼国是黑暗时代后期崛起的新兴国家，正处于国力上升期。作为鹿熊双方争夺与扶持的焦点，狼国领导层在大国夹缝中执行<strong>危险的平衡策略</strong>——既不倒向任何一方，又同时从双方获取利益。狮族战争后，狼国积极发展热武器与核武器，成为具备硬实力的&quot;危险平衡者&quot;。</p><h2 id="当前格局" tabindex="-1">当前格局 <a class="header-anchor" href="#当前格局" aria-label="Permalink to &quot;当前格局&quot;">​</a></h2><p>黑暗时代结束后，大陆各种族重新建立政治实体。鹿熊冷战持续至今，双方在科技、军备与中间地带展开长期博弈。狼国境内有一座<strong>红星孤儿院</strong>，收容各族孤儿——这里正是故事的起点。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></p></li><li><p><a href="./共同体时期">共同体时期</a></p></li><li><p><a href="./黑暗时代">黑暗时代</a></p></li><li><p><a href="./../种族/鹿族">鹿族</a></p></li><li><p><a href="./../种族/熊族">熊族</a></p></li><li><p><a href="./../种族/狼族">狼族</a></p></li><li><p><a href="./../../中层/人物/拉斯塔" class="layer-link" data-layer="中层">拉斯塔</a></p></li></ul><hr>',35)])])}const q=t(e,[["render",i]]);export{c as __pageData,q as default};
